package platform

import (
	"errors"
	"time"
)

const copySequenceInterval = 500 * time.Millisecond

type copyTrigger struct {
	repetitions      int
	clipboardUpdated bool
	foreground       uintptr
	clipboardVersion uint64
}

// copySequence counts physical C presses, not clipboard notifications or repeats
// generated by holding C. It stores no input text or clipboard contents.
type copySequence struct {
	pressCount      int
	copyHeld        bool
	foreground      uintptr
	clipboardBefore uint64
	lastPress       time.Time
}

func (sequence *copySequence) press(now time.Time, foreground uintptr, clipboardVersion uint64) copyTrigger {
	if sequence.copyHeld {
		return copyTrigger{}
	}
	// WM_TIMER has low priority. Resolve a deadline before processing a later
	// physical press rather than losing the previous gesture to queue timing.
	expired := copyTrigger{}
	if now.Sub(sequence.lastPress) > copySequenceInterval {
		expired = sequence.complete(now, foreground, clipboardVersion)
	}
	sequence.copyHeld = true
	if foreground == 0 {
		sequence.cancel()
		return copyTrigger{}
	}
	if sequence.foreground != foreground || now.Sub(sequence.lastPress) > copySequenceInterval {
		sequence.cancel()
	}
	// Five or more presses are deliberately not treated as three or four.
	if sequence.pressCount < 5 {
		sequence.pressCount++
	}
	sequence.foreground = foreground
	sequence.clipboardBefore = clipboardVersion
	sequence.lastPress = now
	return expired
}

func (sequence *copySequence) release() { sequence.copyHeld = false }

func (sequence *copySequence) cancel() {
	sequence.pressCount = 0
	sequence.foreground = 0
	sequence.clipboardBefore = 0
	sequence.lastPress = time.Time{}
}

func (sequence *copySequence) complete(now time.Time, foreground uintptr, clipboardVersion uint64) copyTrigger {
	if sequence.pressCount == 0 {
		return copyTrigger{}
	}
	if foreground != sequence.foreground || foreground == 0 {
		sequence.cancel()
		return copyTrigger{}
	}
	if now.Sub(sequence.lastPress) < copySequenceInterval {
		return copyTrigger{}
	}
	pressCount := sequence.pressCount
	copied := clipboardVersion != 0 && clipboardVersion != sequence.clipboardBefore
	sequence.cancel()
	if sequence.copyHeld || (pressCount != 3 && pressCount != 4) {
		return copyTrigger{}
	}
	return copyTrigger{repetitions: pressCount, clipboardUpdated: copied, foreground: foreground, clipboardVersion: clipboardVersion}
}

func captureClipboardCopyAtSnapshot(trigger copyTrigger, foreground func() uintptr, capture func() (ClipboardCapture, error)) (ClipboardCapture, error) {
	if trigger.foreground == 0 || trigger.clipboardVersion == 0 || foreground() != trigger.foreground {
		return ClipboardCapture{}, errors.New("copy gesture target changed before capture")
	}
	result, err := capture()
	if err != nil {
		return ClipboardCapture{}, err
	}
	if result.version != trigger.clipboardVersion || foreground() != trigger.foreground {
		return ClipboardCapture{}, errors.New("copy gesture target or clipboard changed before capture")
	}
	return result, nil
}
